def maxSumTrionic(nums):
    n = len(nums)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + nums[i]
    incStart = [0] * n
    minInc = [0] * n
    for i in range(n):
        if i > 0 and nums[i - 1] < nums[i]:
            incStart[i] = incStart[i - 1]
            minInc[i] = min(minInc[i - 1], prefix[i])
        else:
            incStart[i] = i
            minInc[i] = prefix[i]
    incEnd = [0] * n
    rmax = [0] * n
    for i in range(n - 1, -1, -1):
        if i < n - 1 and nums[i] < nums[i + 1]:
            incEnd[i] = incEnd[i + 1]
            rmax[i] = max(prefix[i + 1], rmax[i + 1])
        else:
            incEnd[i] = i
            rmax[i] = prefix[i + 1]
    decTop = [0] * n
    for i in range(n):
        if i > 0 and nums[i - 1] > nums[i]:
            decTop[i] = decTop[i - 1]
        else:
            decTop[i] = i
    ans = -(1 << 62)
    for q in range(1, n - 1):
        if nums[q - 1] > nums[q] < nums[q + 1]:
            p = decTop[q]
            if p < 1 or p >= q:
                continue
            if not (nums[p - 1] < nums[p]):
                continue
            cand = rmax[q + 1] - minInc[p - 1]
            if cand > ans:
                ans = cand
    return ans
